/* From Uiverse.io by Satwinder04 - Tags: loader */
.__UIV_SCOPE__ .loader3 {
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .bars {
  width: 10px;
  height: 20px;
  margin: 0 2px;
  border-radius: 4px;
  animation: loader3 3s ease-in-out infinite;
}

.__UIV_SCOPE__ .bar1 {
  background-color: #4285F4;
  animation-delay: -0.8s;
}

.__UIV_SCOPE__ .bar2 {
  background-color: #4285F4;
  animation-delay: -0.7s;
}

.__UIV_SCOPE__ .bar3 {
  background-color: #4285F4;
  animation-delay: -0.6s;
}

.__UIV_SCOPE__ .bar4 {
  background-color: #4285F4;
  animation-delay: -0.5s;
}

.__UIV_SCOPE__ .bar5 {
  background-color: #4285F4;
  animation-delay: -0.4s;
}

.__UIV_SCOPE__ .bar6 {
  background-color: #4285F4;
  animation-delay: -0.3s;
}

.__UIV_SCOPE__ .bar7 {
  background-color: #4285F4;
  animation-delay: -0.2s;
}

.__UIV_SCOPE__ .bar8 {
  background-color: #4285F4;
  animation-delay: -0.1s;
}

.__UIV_SCOPE__ .bar9 {
  background-color: #4285F4;
  animation-delay: 0s;
}

.__UIV_SCOPE__ .bar10 {
  background-color: #4285F4;
  animation-delay: 0.1s;
}

@keyframes loader3 {
  0% {
    transform: scale(1);
  }

  20% {
    transform: scale(1, 2.32);
  }

  40% {
    transform: scale(1);
  }
}
